Translate the following Java 8 code to Python 3 code. The code reads and writes I/O from the console. Your translated code should have the exact same functionality as the given code, meaning that it should have the same output for any given input.
Print your translated code and also the confidence score you give to your translation. The confidence score should be a number between 0 and 1. The format of the output should be:
<translated_code>
<your_translated_code>
</translated_code>
<confidence>
<your_confidence_score>
</confidence>
Do not provide any other text or markdown fences.

Here is the original Java 8 code you have to translate:
<original_code>
import java.io.*;

public class Main {
    public static void main(String[] args) throws IOException {
        byte[] data = readAll(System.in);
        String input = new String(data, "UTF-8").trim();
        String[] tokens = input.split("\\s+");
        long n = Integer.parseInt(tokens[0]);
        long m = Integer.parseInt(tokens[1]);
        long answer = solve(n, m);
        PrintWriter out = new PrintWriter(System.out);
        out.println(answer);
        out.close();
    }

    private static byte[] readAll(InputStream in) throws IOException {
        ByteArrayOutputStream buffer = new ByteArrayOutputStream();
        byte[] chunk = new byte[4096];
        int read;
        while ((read = in.read(chunk)) != -1) {
            buffer.write(chunk, 0, read);
        }
        return buffer.toByteArray();
    }

    private static long solve(long n, long m) {
        if (n > m) {
            long t = n;
            n = m;
            m = t;
        }
        if (n == 1) {
            long[] subtract = {0, 1, 2, 3, 2, 1};
            return m - subtract[(int) (m % 6)];
        }
        if (n == 2) {
            if (m == 2) return 0;
            if (m == 3) return 4;
            if (m == 7) return 12;
            return m * 2;
        }
        return (n * m) & ~1L;
    }
}
